int minDepth(struct TreeNode *root) {
  if (root == NULL) return 0;
  if (root->left == NULL && root->right == NULL) return 1;
  if (root->left == NULL) return minDepth(root->right) + 1;
  if (root->right == NULL) return minDepth(root->left) + 1;
  int left = minDepth(root->left);
  int right = minDepth(root->right);
  return (left < right ? left : right) + 1;
}

class Solution {
public:
  int minDepth(TreeNode *root) {
    if (root == nullptr) return 0;
    if (root->left == nullptr && root->right == nullptr) return 1;
    if (root->left == nullptr) return minDepth(root->right) + 1;
    if (root->right == nullptr) return minDepth(root->left) + 1;
    return 1 + min(minDepth(root->left), minDepth(root->right));
  }
};

func minDepth(root *TreeNode) int {
	if root == nil {
		return 0
	}
	if root.Left == nil && root.Right == nil {
		return 1
	}
	if root.Left == nil {
		return minDepth(root.Right) + 1
	}
	if root.Right == nil {
		return minDepth(root.Left) + 1
	}
	left := minDepth(root.Left)
	right := minDepth(root.Right)
	if left < right {
		return left + 1
	}
	return right + 1
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  public int minDepth(TreeNode root) {
    if (root == null) {
      return 0;
    }
    if (root.left == null && root.right == null) {
      return 1;
    }
    if (root.left == null) {
      return minDepth(root.right) + 1;
    }
    if (root.right == null) {
      return minDepth(root.left) + 1;
    }
    return 1 + Math.min(minDepth(root.left), minDepth(root.right));
  }
}

class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        if root is None:
            return 0
        if root.left is None and root.right is None:
            return 1
        if root.left is None:
            return self.minDepth(root.right) + 1
        if root.right is None:
            return self.minDepth(root.left) + 1
        return 1 + min(self.minDepth(root.left), self.minDepth(root.right))

impl Solution {
  pub fn min_depth(root: Option<Box<TreeNode>>) -> i32 {
    match root {
      None => 0,
      Some(node) => {
        match (node.left.as_ref(), node.right.as_ref()) {
          (None, None) => 1,
          (Some(_), None) => 1 + Solution::min_depth(node.left),
          (None, Some(_)) => 1 + Solution::min_depth(node.right),
          (Some(_), Some(_)) => {
            1 + std::cmp::min(Solution::min_depth(node.left), Solution::min_depth(node.right))
          }
        }
      }
    }
  }
}

const minDepth = (root: TreeNode | null): number => {
  if (!root) return 0;
  if (!root.left && !root.right) return 1;
  if (!root.left) return minDepth(root.right) + 1;
  if (!root.right) return minDepth(root.left) + 1;
  return 1 + Math.min(minDepth(root.left), minDepth(root.right));
};
